contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint sumBefore, uint sumAfter) public {
        c.SetMinSum(sumBefore); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool setMinAfterInitReverted;
        c.SetMinSum(sumAfter); bool __rev0 = __ESBMC_reverted(); if (__rev0) { setMinAfterInitReverted = true; } else { setMinAfterInitReverted = false; }

        bool setLogAfterInitReverted;
        c.SetLogFile(address(this)); bool __rev1 = __ESBMC_reverted(); if (__rev1) { setLogAfterInitReverted = true; } else { setLogAfterInitReverted = false; }

        assert(setMinAfterInitReverted && setLogAfterInitReverted);
    }
}

