// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 sumBefore, uint256 sumAfter) internal {
        try c.SetMinSum(sumBefore) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool setMinAfterInitReverted;
        try c.SetMinSum(sumAfter) { setMinAfterInitReverted = false; } catch { setMinAfterInitReverted = true; }
        bool setLogAfterInitReverted;
        try c.SetLogFile(address(this)) { setLogAfterInitReverted = false; } catch { setLogAfterInitReverted = true; }
        assertTrue(setMinAfterInitReverted && setLogAfterInitReverted);
    }

    function testFuzz_run(uint256 sumBefore, uint256 sumAfter) public {
        _run(sumBefore, sumAfter);
    }

    receive() external payable {}
}
